// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount <= address(this).balance);
        vm.assume(c.smartfix_owner() != address(this));
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
